import{_ as t,o as a,c as i,a2 as l}from"./chunks/framework.ktMMbWgA.js";const p=JSON.parse('{"title":"学员长期资源清单（2026-Q2）","description":"","frontmatter":{},"headers":[],"relativePath":"public/lectures/L35-predictions/demo/resources.md","filePath":"public/lectures/L35-predictions/demo/resources.md","lastUpdated":null}'),r={name:"public/lectures/L35-predictions/demo/resources.md"};function o(n,e,s,c,u,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="学员长期资源清单-2026-q2" tabindex="-1">学员长期资源清单（2026-Q2） <a class="header-anchor" href="#学员长期资源清单-2026-q2" aria-label="Permalink to &quot;学员长期资源清单（2026-Q2）&quot;">​</a></h1><blockquote><p>以下都是讲师亲测、目前仍活跃维护的来源。 优先级：先订满第 1 类（4-5 个），再扩展。</p></blockquote><h2 id="_1️⃣-newsletter-每周必读" tabindex="-1">1️⃣ Newsletter（每周必读） <a class="header-anchor" href="#_1️⃣-newsletter-每周必读" aria-label="Permalink to &quot;1️⃣ Newsletter（每周必读）&quot;">​</a></h2><ul><li><strong>Import AI</strong> (Jack Clark, Anthropic 联合创始人) — 每周一篇政策 + 技术</li><li><strong>The Batch</strong> (Andrew Ng) — DeepLearning.AI 出品，技术 + 教育视角</li><li><strong>Stratechery</strong> (Ben Thompson) — AI 商业战略最深刻</li><li><strong>Last Week in AI</strong> — 周更，覆盖工业落地</li><li><strong>Latent Space</strong> — Practitioner 视角的 podcast + newsletter</li></ul><h2 id="_2️⃣-实验室博客-精读-不要订全文-rss" tabindex="-1">2️⃣ 实验室博客（精读，不要订全文 RSS） <a class="header-anchor" href="#_2️⃣-实验室博客-精读-不要订全文-rss" aria-label="Permalink to &quot;2️⃣ 实验室博客（精读，不要订全文 RSS）&quot;">​</a></h2><ul><li>Anthropic Research / OpenAI Research / DeepMind Blog</li><li>METR / UK AISI / NIST AISI（安全方向必读）</li><li>Hugging Face Blog（开源 + 教程）</li></ul><h2 id="_3️⃣-twitter-x-关注列表-10-20-人足够" tabindex="-1">3️⃣ Twitter / X 关注列表（10-20 人足够） <a class="header-anchor" href="#_3️⃣-twitter-x-关注列表-10-20-人足够" aria-label="Permalink to &quot;3️⃣ Twitter / X 关注列表（10-20 人足够）&quot;">​</a></h2><ul><li>从你已知的最佳工程师/研究员开始；用 list 隔离信息流</li><li>不要追求&quot;全网最新&quot;——选 10-20 人深读</li></ul><h2 id="_4️⃣-社群" tabindex="-1">4️⃣ 社群 <a class="header-anchor" href="#_4️⃣-社群" aria-label="Permalink to &quot;4️⃣ 社群&quot;">​</a></h2><ul><li>Hugging Face Discord（开源最大）</li><li>LocalLLaMA Reddit（端侧 + 量化）</li><li>r/MachineLearning（学术为主）</li><li>中文：知乎机器学习专栏 + AI 公众号 5-10 个（避免娱乐化的）</li></ul><h2 id="_5️⃣-必看代码仓库-star-偶尔-git-pull" tabindex="-1">5️⃣ 必看代码仓库（star + 偶尔 git pull） <a class="header-anchor" href="#_5️⃣-必看代码仓库-star-偶尔-git-pull" aria-label="Permalink to &quot;5️⃣ 必看代码仓库（star + 偶尔 git pull）&quot;">​</a></h2><ul><li>vllm-project/vllm（推理引擎）</li><li>langchain-ai/langgraph 或 vercel/ai 或 mastra-ai/mastra（agent）</li><li>microsoft/markitdown（文档处理）</li><li>anthropic-ai/courses &amp; quickstarts</li><li>openai/openai-cookbook</li><li>Significant-Gravitas/AutoGPT（保留教学价值）</li></ul><h2 id="_6️⃣-课程外的进阶阅读-按时序" tabindex="-1">6️⃣ 课程外的进阶阅读（按时序） <a class="header-anchor" href="#_6️⃣-课程外的进阶阅读-按时序" aria-label="Permalink to &quot;6️⃣ 课程外的进阶阅读（按时序）&quot;">​</a></h2><ol><li><em>Bishop</em>, Pattern Recognition and ML（数学基础）</li><li><em>Goodfellow et al</em>, Deep Learning（系统化深度学习）</li><li><em>Sutton &amp; Barto</em>, RL: An Introduction（RL 圣经）</li><li><em>Stuart Russell</em>, Human Compatible（对齐哲学）</li><li><em>Bostrom</em>, Superintelligence（远期 x-risk 视角）</li></ol><h2 id="⚠️-反建议" tabindex="-1">⚠️ 反建议 <a class="header-anchor" href="#⚠️-反建议" aria-label="Permalink to &quot;⚠️ 反建议&quot;">​</a></h2><ul><li>不要订阅&quot;AI 日报&quot;类聚合 — 会让你每天读 100 条噪音</li><li>不要追每一个新模型 — 等社区评估 1 周再看</li><li>不要在 Twitter 上吵架 — 写代码时间 &gt; 辩论时间</li><li>不要相信任何&quot;AGI 倒计时&quot;具体年份 — 包括我说的</li></ul><hr><p><strong>最后</strong>：信息消费 ≤ 1 小时/天。其余时间写代码、做项目、找人聊。</p>',18)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
